from fizzbuzz import fizzbuzz

def test_basic():
    assert fizzbuzz(15) == ['1','2','Fizz','4','Buzz','Fizz','7','8','Fizz','Buzz','11','Fizz','13','14','FizzBuzz']

def test_length():
    assert len(fizzbuzz(100)) == 100

def test_n_one():
    assert fizzbuzz(1) == ['1']

def test_n_three():
    assert fizzbuzz(3) == ['1','2','Fizz']

def test_n_five():
    assert fizzbuzz(5) == ['1','2','Fizz','4','Buzz']

from word_count import count_words

def test_simple():
    assert count_words('hello world hello') == {'hello': 2, 'world': 1}

def test_case_insensitive():
    assert count_words('Hello HELLO hello') == {'hello': 3}

def test_punctuation():
    assert count_words('hello, world! hello.') == {'hello': 2, 'world': 1}

def test_empty():
    assert count_words('') == {}

def test_whitespace_only():
    assert count_words('   \t\n  ') == {}

def test_multi_punct():
    assert count_words('What?! What?!') == {'what': 2}

from flatten import flatten

def test_simple_nested():
    assert flatten({'a': {'b': 1, 'c': {'d': 2}}}) == {'a.b': 1, 'a.c.d': 2}

def test_flat():
    assert flatten({'a': 1, 'b': 2}) == {'a': 1, 'b': 2}

def test_empty():
    assert flatten({}) == {}

def test_custom_sep():
    assert flatten({'a': {'b': 1}}, sep='/') == {'a/b': 1}

def test_list_preserved():
    result = flatten({'a': [1, 2, 3], 'b': {'c': [4, 5]}})
    assert result == {'a': [1, 2, 3], 'b.c': [4, 5]}

def test_deep_nesting():
    assert flatten({'a': {'b': {'c': {'d': {'e': 'deep'}}}}}) == {'a.b.c.d.e': 'deep'}
